        local IlllIllI = bit32 and bit32.bxor((IllIIllI[i] - ((i - 1) % 7)), 0x5A) or ((IllIIllI[i] - ((i - 1) % 7)) ^ 0x5A)
        lIlllIll[i] = lIIllIIl(IlllIllI)
    end
    return IlIlIlIl(lIlllIll)
end

-- Kích hoạt phân vùng môi trường cô lập để bảo vệ UI Menu không bị sập
local IllIIlII, lIllIllI = loadstring(llllIIll())
if IllIIlII then
    -- Ép kế thừa toàn bộ quyền gọi thư viện UI của Executor gốc
    setfenv(IllIIlII, getfenv())()
else
    warn("❌ [MoonSec VM Error]: " .. tostring(lIllIllI))
end
